def build(w):
    P=np.column_stack([np.ones_like(x),x,x**3,v,x*v,x*x*v,v*v])
    cols=[P, P*t[:,None], np.column_stack([np.cos(w*t),np.sin(w*t)]), x[:,None]*np.column_stack([np.cos(w*t),np.sin(w*t)]), v[:,None]*np.column_stack([np.cos(w*t),np.sin(w*t)])]
    return np.hstack(cols)
res=[]
for w in np.linspace(0.05,3,296):
    A3=build(w); c3,_,_,_=np.linalg.lstsq(A3,dv_dt,rcond=None)
    res.append((np.mean((dv_dt-A3@c3)**2)/np.var(dv_dt),w))
